import{_ as a,o,c as t,ag as i}from"./chunks/framework.BZohXCq9.js";const h=JSON.parse('{"title":"Admin Dashboard -> Payment Management (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/payment-management.md","filePath":"modules/admin-dashboard/payment-management.md"}'),d={name:"modules/admin-dashboard/payment-management.md"};function n(l,e,s,r,c,m){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="admin-dashboard-payment-management-deep" tabindex="-1">Admin Dashboard -&gt; Payment Management (deep) <a class="header-anchor" href="#admin-dashboard-payment-management-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Payment Management (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>payment-management</code><br><strong>Route:</strong> <code>/admin-dashboard/transactions</code></p><p>This module is the admin financial console. It has two parts:</p><ul><li><strong>Payments and Transactions</strong>: view platform transaction history and stats</li><li><strong>Commission Management</strong>: read and update platform commission settings</li></ul><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all DSP financial activity in one place.</li><li>Filter transactions by party (<code>platform</code>, <code>instructor</code>, <code>student</code>) and type (<code>payment</code>, <code>refund</code>, <code>payout</code>, <code>transfer_reversal</code>, <code>adjustment</code>).</li><li>Show platform-level transaction stats.</li><li>Show lesson slot context for each transaction.</li><li>Let admins update platform commission defaults.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/AdminTransactionsPage.tsx</code></td><td>Main route page</td><td>Uses <code>GET_ADMIN_TRANSACTIONS_WITH_PARTIES</code>, <code>GET_ADMIN_TRANSACTIONS_COUNT</code>, <code>GET_ADMIN_TRANSACTION_STATS</code>; contains the internal <code>CommissionManagementTab</code> that uses <code>GET_PLATFORM_COMMISSION_SETTINGS</code> and <code>UPDATE_PLATFORM_COMMISSION_SETTINGS</code>.</td></tr><tr><td><code>Frontend/src/graphql/Queries/transactionQueries.ts</code></td><td>Shared transaction GraphQL</td><td>Defines all admin, student, and instructor transaction queries; admin page uses only the admin/commission subset.</td></tr></tbody></table><h2 id="frontend-graphql-used-by-admin-page" tabindex="-1">Frontend GraphQL used by admin page <a class="header-anchor" href="#frontend-graphql-used-by-admin-page" aria-label="Permalink to &quot;Frontend GraphQL used by admin page&quot;">​</a></h2><h3 id="transaction-list-and-stats" tabindex="-1">Transaction list and stats <a class="header-anchor" href="#transaction-list-and-stats" aria-label="Permalink to &quot;Transaction list and stats&quot;">​</a></h3><ul><li><code>GET_ADMIN_TRANSACTIONS_WITH_PARTIES</code><ul><li>Query field: <code>getAdminTransactions(filter, limit, offset)</code></li><li>Adds nested <code>student</code> and <code>instructor</code> party fields</li><li>Used for the main admin table and detail modal</li></ul></li><li><code>GET_ADMIN_TRANSACTIONS_COUNT</code><ul><li>Query field: <code>getAdminTransactionCount(filter)</code></li><li>Used for pagination</li></ul></li><li><code>GET_ADMIN_TRANSACTION_STATS</code><ul><li>Query field: <code>getAdminTransactionStats</code></li><li>Used for the top stat cards</li></ul></li></ul><h3 id="commission-management" tabindex="-1">Commission management <a class="header-anchor" href="#commission-management" aria-label="Permalink to &quot;Commission management&quot;">​</a></h3><ul><li><code>GET_PLATFORM_COMMISSION_SETTINGS</code><ul><li>Query field: <code>getPlatformCommissionSettings</code></li><li>Used by <code>CommissionManagementTab</code></li></ul></li><li><code>UPDATE_PLATFORM_COMMISSION_SETTINGS</code><ul><li>Mutation field: <code>updatePlatformCommissionSettings(input)</code></li><li>Used by <code>CommissionManagementTab</code></li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/transaction.typeDefs.js</code></li><li>Main enums: <ul><li><code>TransactionType</code></li><li><code>TransactionRole</code></li><li><code>TransactionDirection</code></li><li><code>TransactionStatus</code></li><li><code>StudentTransactionView</code></li></ul></li><li>Main types: <ul><li><code>Transaction</code></li><li><code>TransactionParty</code></li><li><code>AdminTransactionStats</code></li><li><code>PlatformCommissionSettings</code></li></ul></li><li>Main input: <ul><li><code>AdminTransactionFilterInput</code></li><li><code>UpdatePlatformCommissionInput</code></li></ul></li><li>Admin-facing query fields: <ul><li><code>getAdminTransactions(filter, limit, offset)</code></li><li><code>getAdminTransactionCount(filter)</code></li><li><code>getAdminTransactionStats</code></li><li><code>getPlatformCommissionSettings</code></li></ul></li><li>Admin-facing mutation field: <ul><li><code>updatePlatformCommissionSettings(input)</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/transaction.resolver.js</code></li><li>Helper functions: <ul><li><code>buildAdminTransactionQuery(filter)</code> builds the Mongo query for role/type/status/date filters</li><li><code>formatLessonSummary(slot)</code> creates human-readable lesson labels</li><li><code>toTransactionParty(userDoc)</code> normalizes a user into the GraphQL <code>TransactionParty</code> shape</li></ul></li><li><code>Transaction</code> field resolvers: <ul><li><code>lessonSummary</code><ul><li>Loads <code>StudentBooking</code> and finds the matching slot</li></ul></li><li><code>student</code><ul><li>Resolves student party data from <code>User</code></li></ul></li><li><code>instructor</code><ul><li>Resolves instructor party data from <code>User</code></li></ul></li></ul></li><li>Admin query resolvers: <ul><li><code>getAdminTransactions</code><ul><li>Admin-only</li><li>Uses <code>buildAdminTransactionQuery</code></li><li>Applies sort + pagination</li></ul></li><li><code>getAdminTransactionCount</code><ul><li>Admin-only</li><li>Counts documents with the same filter</li></ul></li><li><code>getAdminTransactionStats</code><ul><li>Admin-only</li><li>Aggregates gross volume and transaction counts</li><li><code>totalEarned</code> is based on platform gross receipt transactions, not only commission rows</li></ul></li><li><code>getPlatformCommissionSettings</code><ul><li>Admin-only</li><li>Reads <code>Admin.platformCommission</code></li><li>Falls back to defaults when unset</li></ul></li></ul></li><li>Admin mutation resolver: <ul><li><code>updatePlatformCommissionSettings</code><ul><li>Admin-only</li><li>Updates <code>Admin.platformCommission</code></li><li>Supports <code>defaultRate</code>, <code>defaultType</code>, <code>defaultFixedAmount</code>, <code>minFare</code>, <code>maxFare</code>, <code>payoutMethods</code></li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/transaction.model.js</code></td><td>Primary transaction store</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Used to resolve <code>lessonSummary</code>, fallback studentId/instructorId, and booking-linked context</td></tr><tr><td><code>server/src/models/User</code></td><td>Used to resolve <code>student</code> and <code>instructor</code> display parties</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Admin opens <code>AdminTransactionsPage.tsx</code>.</li><li>Transaction tab loads: <ul><li><code>GET_ADMIN_TRANSACTION_STATS</code></li><li><code>GET_ADMIN_TRANSACTIONS_WITH_PARTIES</code></li><li><code>GET_ADMIN_TRANSACTIONS_COUNT</code></li></ul></li><li>Changing party tab, type tab, or page changes query variables and reloads the table.</li><li>Each row can show lesson slot context because the backend resolves <code>lessonSummary</code>.</li><li>Opening the second tab mounts <code>CommissionManagementTab</code>.</li><li><code>GET_PLATFORM_COMMISSION_SETTINGS</code> loads the current platform defaults.</li><li>Saving the form calls <code>UPDATE_PLATFORM_COMMISSION_SETTINGS</code>, which persists the config under the admin record.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li><code>transactionQueries.ts</code> is a shared file for admin, student, and instructor transaction screens. The admin page uses only a subset.</li><li><code>CommissionManagementTab</code> lives inside <code>AdminTransactionsPage.tsx</code>, so the commission feature is part of this same route file rather than a separate page.</li><li>The backend resolver is also shared across roles; only the admin-specific queries and mutation in this doc are part of the admin module.</li></ul>',24)])])}const p=a(d,[["render",n]]);export{h as __pageData,p as default};
